tier2_shebang_firstline.patterns:
#!/usr/bin/env node → javascript
#!/usr/bin/env python → python  
#!/usr/bin/env bash → bash
#!/usr/bin/env ruby → ruby

grammar_discovery_process.runtime_detection:

fn discover_language(path: &Path) -> LanguageId {
    // 1. Extension → probable_language
    let probable = extension_to_language(path.extension())?;

    // 2. Shebang check
    let shebang = read_first_line(path)?;
    if let Some(lang) = shebang_to_language(&shebang) {
        return lang;
    }

    // 3. Try parse with probable grammar
    if let Ok(tree) = try_parse(probable_grammar(), source) {
        return probable;
    }

    // 4. Fallback: try grammar family
    for candidate in grammar_family(probable) {
        if try_parse(candidate, source).is_ok() {
            return candidate;
        }
    }

    LanguageId::Unknown
}
